import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, writeFileSync, utimesSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';

const BOT = process.env.BOT_PATH;
const stateDir = mkdtempSync(path.join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = stateDir;
const { reserve, release } = await import(BOT);

const H = 3600e3, M = 60e3;
const T0 = new Date('2026-10-22T10:00:00Z');
const at = (ms) => new Date(T0.getTime() + ms);
const req = (o = {}) => ({ userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 90, ...o });
let n = 0; const ok = (name) => console.log(`ok ${++n} - ${name}`);

// 1. cap per window, gap 0 so only the cap applies
{
  const r = req({ minGapMinutes: 0, userId: 'cap' });
  for (let i = 0; i < 3; i++) {
    const res = await reserve(r, at(i * 1000));
    assert.equal(res.allowed, true); assert.equal(res.reason, null); assert.match(res.reservationId, /^[0-9a-f]{64}\./);
  }
  assert.deepEqual(await reserve(r, at(5000)).then(({ allowed, reason, reservationId }) => ({ allowed, reason, reservationId })),
    { allowed: false, reason: 'max_per_window', reservationId: null });
  ok('cap of 3 per window enforced, blocked attempt has null id');
}

// 2. min gap
{
  const r = req({ userId: 'gap' });
  assert.equal((await reserve(r, at(0))).allowed, true);
  const early = await reserve(r, at(89 * M));
  assert.equal(early.reason, 'min_gap');
  assert.equal((await reserve(r, at(90 * M))).allowed, true);
  ok('min gap of 90 min enforced; boundary exactly 90 min allowed');
}

// 3. sliding window: the first send expires exactly at +24h
{
  const r = req({ userId: 'slide', maxPerWindow: 2, minGapMinutes: 0 });
  const a = await reserve(r, at(0));
  await reserve(r, at(1 * H));
  assert.equal((await reserve(r, at(2 * H))).reason, 'max_per_window');
  assert.equal((await reserve(r, at(24 * H - 1))).reason, 'max_per_window'); // a still counts
  assert.equal((await reserve(r, at(24 * H))).allowed, true); // a has aged out
  assert.ok(a.reservationId);
  ok('sliding window: a send counts for exactly windowHours');
}

// 4. release frees the slot, idempotent, works from another module instance
{
  const r = req({ userId: 'rel', maxPerWindow: 1, minGapMinutes: 0 });
  const a = await reserve(r, at(0));
  assert.equal((await reserve(r, at(1))).reason, 'max_per_window');
  const other = await import(`${BOT}?fresh=${Math.random()}`);
  assert.equal(await other.release(a.reservationId), true);
  assert.equal(await release(a.reservationId), false);   // already released
  assert.equal(await release('not-an-id'), false);
  assert.equal((await reserve(r, at(2))).allowed, true);  // slot is back
  ok('release frees slot from another instance; double release is a no-op');
}

// 5. released sends do not start the min-gap clock
{
  const r = req({ userId: 'gaprel' });
  const a = await reserve(r, at(0));
  await release(a.reservationId);
  assert.equal((await reserve(r, at(1 * M))).allowed, true);
  ok('released reservation does not count toward min gap');
}

// 6. persistence across a fresh process
{
  const r = req({ userId: 'persist', maxPerWindow: 1, minGapMinutes: 0 });
  assert.equal((await reserve(r, at(0))).allowed, true);
  const out = await new Promise((resolve, reject) => {
    const c = spawn(process.execPath, ['-e', `
      const { reserve } = await import(${JSON.stringify(BOT)});
      const r = await reserve({ userId: 'persist', maxPerWindow: 1, windowHours: 24, minGapMinutes: 0 }, new Date(${at(1000).getTime()}));
      console.log(r.reason);`], { env: process.env, stdio: ['ignore', 'pipe', 'inherit'] });
    let s = ''; c.stdout.on('data', (d) => (s += d)); c.on('close', () => resolve(s.trim()));
    c.on('error', reject);
  });
  assert.equal(out, 'max_per_window');
  ok('history survives across processes (restart)');
}

// 7. validation
{
  await assert.rejects(reserve(req({ maxPerWindow: -1 }), at(0)), RangeError);
  await assert.rejects(reserve(req({ windowHours: 0 }), at(0)), RangeError);
  await assert.rejects(reserve(req({ minGapMinutes: NaN }), at(0)), RangeError);
  await assert.rejects(reserve(req({ userId: '' }), at(0)), TypeError);
  await assert.rejects(reserve(req(), Date.now()), TypeError);
  ok('invalid inputs rejected');
}

// 8. stale lock from a crashed worker is broken
{
  const r = req({ userId: 'stale', minGapMinutes: 0 });
  const { createHash } = await import('node:crypto');
  const key = createHash('sha256').update('stale').digest('hex');
  mkdirSync(path.join(stateDir, 'locks'), { recursive: true });
  const lock = path.join(stateDir, 'locks', `${key}.lock`);
  mkdirSync(lock);
  const old = new Date(Date.now() - 60e3); utimesSync(lock, old, old);
  const res = await reserve(r, at(0));
  assert.equal(res.allowed, true);
  ok('stale lock (crashed holder) is broken and reserve proceeds');
}

// 9. concurrency across real processes: 12 workers x 20 attempts, cap 3, gap 0
async function fanOut(userId, req, nowMs, procs = 12, attempts = 20) {
  const script = `
    const { reserve } = await import(${JSON.stringify(BOT)});
    const out = [];
    const r = ${JSON.stringify(req)};
    const ps = [];
    for (let i = 0; i < ${attempts}; i++) ps.push(reserve({ ...r, userId: ${JSON.stringify(userId)} }, new Date(${nowMs})).then(x => out.push(x.allowed)));
    await Promise.all(ps);
    console.log(JSON.stringify(out.filter(Boolean).length));`;
  const runs = Array.from({ length: procs }, () => new Promise((resolve, reject) => {
    const c = spawn(process.execPath, ['-e', `(async()=>{${script}})()`], { env: process.env, stdio: ['ignore', 'pipe', 'inherit'] });
    let s = ''; c.stdout.on('data', (d) => (s += d)); c.on('close', (code) => code === 0 ? resolve(Number(s)) : reject(new Error('child ' + code)));
  }));
  return (await Promise.all(runs)).reduce((a, b) => a + b, 0);
}
{
  const total = await fanOut('race_cap', { maxPerWindow: 3, windowHours: 24, minGapMinutes: 0 }, T0.getTime());
  assert.equal(total, 3, `cap race allowed ${total}`);
  ok('concurrent cross-process race: exactly 3 allowed under cap of 3');
}
{
  const total = await fanOut('race_gap', { maxPerWindow: 100, windowHours: 24, minGapMinutes: 90 }, T0.getTime());
  assert.equal(total, 1, `gap race allowed ${total}`);
  ok('concurrent cross-process race: exactly 1 allowed under 90 min gap');
}

console.log(`\nall ${n} checks passed; state dir ${stateDir}`);
EOF
